    return np.array(centers[:n])


def optimize_with_cobyla(centers, n):
    """
    Use scipy.optimize.minimize with COBYLA to optimize circle positions.
    Maximizes sum of radii while penalizing overlaps and boundary violations.

    COBYLA is suitable for non-smooth constraint problems without gradients.
    """
    x0 = centers.flatten()
    bounds = [(0.01, 0.99)] * (2 * n)

    def objective(x):
        """Negative sum of radii (we minimize, so negative)."""
        c = x.reshape(-1, 2)
        r = compute_radii(c, n)
        # Penalize overlaps
        penalty = 0
        for i in range(n):
            for j in range(i+1, n):
                d = np.linalg.norm(c[i] - c[j])
                if r[i] + r[j] > d:
                    penalty += 100 * (r[i] + r[j] - d) ** 2
        return -np.sum(r) + penalty

    result = minimize(objective, x0, method='COBYLA', bounds=bounds,
                     options={'maxiter': 500, 'rhobeg': 0.05})

    if result.success:
        opt_centers = result.x.reshape(-1, 2)
        opt_radii = compute_radii(opt_centers, n)
        opt_sum = np.sum(opt_radii)
        return opt_centers, opt_radii, opt_sum

    return None


def compute_radii(centers, n):
    """Compute radii based on distance to boundaries and other circles."""
    radii = np.array([min(c[0], c[1], 1-c[0], 1-c[1]) for c in centers])

    for _ in range(100):
